namespace sv_e4232e9a05184de4b4891c6643f95c23.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;

    private readonly List<NotificationItem> _notifications =
    [
        new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.Now.AddMinutes(-30) },
        new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.Now.AddMinutes(-15) },
        new() { Id = 3, Message = "New feature available: Dark Mode.", Timestamp = DateTime.Now.AddMinutes(-5) },
    ];

    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
    }

    public Task<List<NotificationItem>> GetNewNotificationsSinceAsync(int lastId)
    {
        // Simulate occasional new notifications
        if (Random.Shared.Next(3) == 0)
        {
            _notifications.Add(new NotificationItem
            {
                Id = _nextId++,
                Message = $"New event at {DateTime.Now:HH:mm:ss}",
                Timestamp = DateTime.Now
            });
        }

        var newer = _notifications.Where(n => n.Id > lastId).OrderByDescending(n => n.Timestamp).ToList();
        return Task.FromResult(newer);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using sv_e4232e9a05184de4b4891c6643f95c23.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var notification in notifications)
        {
            <li class="list-group-item">
                <strong>@notification.Message</strong>
                <small class="text-muted ms-2">@notification.Timestamp.ToString("g")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationItem>? Notifications { get; set; }

    private List<NotificationItem> notifications = new();
    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        if (Notifications is null)
        {
            Notifications = await NotificationService.GetNotificationsAsync();
        }
        notifications = Notifications;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(5000, ct);

            var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
            var newer = await NotificationService.GetNewNotificationsSinceAsync(lastId);

            if (newer.Count > 0)
            {
                notifications.InsertRange(0, newer);
                Notifications = notifications;
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

